CREATE TABLE sync_secret_bundles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ciphertext BLOB NOT NULL,nonce VARBINARY(12) NOT NULL,encryption_key_id VARCHAR(100) DEFAULT 'master' NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE managed_servers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,alias VARCHAR(200) NOT NULL,alias_key VARCHAR(200) NOT NULL UNIQUE,type VARCHAR(8) NOT NULL CHECK(type IN ('HTTP','SFTP')),description VARCHAR(2000),enabled BOOLEAN NOT NULL,config_revision BIGINT NOT NULL,current_config_id BIGINT,deleted_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE managed_server_configs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,server_id BIGINT NOT NULL REFERENCES managed_servers(id),revision BIGINT NOT NULL,public_config_json CLOB NOT NULL,secret_bundle_id BIGINT REFERENCES sync_secret_bundles(id),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,UNIQUE(server_id,revision));
ALTER TABLE managed_servers ADD CONSTRAINT fk_server_current FOREIGN KEY(current_config_id) REFERENCES managed_server_configs(id);
CREATE TABLE managed_server_trust_certificates(server_config_id BIGINT NOT NULL REFERENCES managed_server_configs(id),source_asset_id BIGINT NOT NULL REFERENCES certificate_assets(id),material_id BIGINT NOT NULL REFERENCES certificate_materials(id),PRIMARY KEY(server_config_id,source_asset_id,material_id));
